import json,os
from collections import Counter
def blocks(total,seps):
    s=set(seps); res=[]; cur=[]
    for i in range(total):
        if i in s:
            if cur: res.append(cur); cur=[]
        else: cur.append(i)
    if cur: res.append(cur)
    return res
def solve(g):
    b=Counter(v for r in g for v in r).most_common(1)[0][0]
    H,W=len(g),len(g[0])
    sr=[i for i in range(H) if len(set(g[i]))==1 and g[i][0]!=b]
    sc=[j for j in range(W) if len({g[i][j] for i in range(H)})==1 and g[0][j]!=b]
    has_r=lambda i:any(g[i][j]!=b for j in range(W) if j not in sc)
    has_c=lambda j:any(g[i][j]!=b for i in range(H) if i not in sr)
    rb=[bk for bk in blocks(H,sr) if any(has_r(i) for i in bk)]
    cb=[bk for bk in blocks(W,sc) if any(has_c(j) for j in bk)]
    rws=rb[0]; cls=cb[0]
    p=[[g[i][j] for j in cls] for i in rws]
    out=[r[:] for r in g]
    for rbk in blocks(H,sr):
        for cbk in blocks(W,sc):
            for a,i in enumerate(rbk):
                for bb,j in enumerate(cbk):
                    out[i][j]=p[a%len(p)][bb%len(p[0])]
    return out
